import os
import sys
import re
(n, k) = map(int, input().split())
chess = [[i for i in input()] for _ in range(n)]

def getVal(c):
	val = [[0] * n for _ in range(n)]
	max_val = 0
	for i in range(n):
		for j in range(n):
			if chess[i][j] == '#':
				val[i][j] = -1
			else:
				val[i][j] = cost(i, j, c, '.')
			max_val = max(max_val, val[i][j])
	return (val, max_val)

def cost(i, j, c, char):
	cout = 0
	if j + 1 < n:
		x = j + 1
		p = c[i][x]
		while p != '#' and x < n:
			p = c[i][x]
			if p == char:
				cout += 1
			x += 1
	if j - 1 >= 0:
		x = j - 1
		p = c[i][x]
		while p != '#' and x >= 0:
			p = c[i][x]
			if p == char:
				cout += 1
			x -= 1
	if i + 1 < n:
		x = i + 1
		p = c[x][j]
		while p != '#' and x < n:
			p = c[x][j]
			if p == char:
				cout += 1
			x += 1
	if i - 1 >= 0:
		x = i - 1
		p = c[x][j]
		while p != '#' and x >= 0:
			p = c[x][j]
			if p == char:
				cout += 1
			x -= 1
	return cout
(val, max_val) = getVal(chess)
curr_c = 0
remain = k
cout_tot = 0
while remain > 0:
	for v in range(max_val + 1):
		if remain == 0:
			break
		for i in range(n):
			if remain == 0:
				break
			for j in range(n):
				if remain == 0:
					break
				if val[i][j] == v and chess[i][j] == '.':
					if cost(i, j, chess, 'o') == curr_c:
						cout_tot += curr_c
						chess[i][j] = 'o'
						remain -= 1
	curr_c += 1
other_count = 0
for i in range(n):
	for j in range(n):
		if chess[i][j] == 'o':
			other_count += cost(i, j, chess, 'o')
print(int(other_count / 2))
